const rows = queries.records.data || [];
const active = rows.filter(r => !['Completed', 'Cancelled'].includes(r.status));
const fmt = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'Unscheduled';
const time = n => String(Math.floor(n)).padStart(2, '0') + ':' + String(Math.round((n % 1) * 60)).padStart(2, '0');
const booking = r => (r.decisions || []).filter(d => d.type === 'booking').at(-1);
const byDue = (a, b) => String(a.due || '9999').localeCompare(String(b.due || '9999'));
const owners = [...new Set(active.map(r => r.owner).filter(Boolean))].slice(0, 3);
return { instructors: owners.map(o => {
  const mine = active.filter(r => r.owner === o).sort(byDue);
  return { name: o, count: mine.length + ' scheduled', lessons: mine.slice(0, 3).map(r => {
    const b = booking(r);
    return { slot: (b && Number.isFinite(Number(b.start)) ? time(Number(b.start)) : 'Unscheduled') + ' · ' + (r.status || ''), name: r.name, due: fmt(r.due) };
  }) };
}) };

const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const items = p?.items || [], dec = p?.decisions || [];
const money = n => Number(n || 0).toLocaleString('en-US', {style: 'currency', currency: 'USD'});
const total = Math.round(items.reduce((n, i) => n + Number(i.quantity || 0) * Number(i.rate || 0), 0) * 100) / 100;
const paid = Math.round(dec.filter(d => d.type === 'payment').reduce((n, d) => n + Number(d.amount || 0), 0) * 100) / 100;
const b = dec.filter(d => d.type === 'booking').at(-1);
const date = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-GB', {day: '2-digit', month: 'short', year: 'numeric'}) : 'Not scheduled';
const time = n => String(Math.floor(n)).padStart(2, '0') + ':' + String(Math.round((n % 1) * 60)).padStart(2, '0');
return {
  context: p?.context || 'Choose a record',
  scope: p?.scope || 'Open a ticket from the register.',
  owner: p?.owner || 'Unassigned',
  booking: b ? date(b.date) + ' · ' + time(b.start) + '–' + time(b.start + b.duration) : 'Schedule after customer approval',
  status: p?.status || 'Not selected',
  total: money(total),
  remaining: money(total - paid) + ' remaining',
  history: (p?.history || []).slice().reverse()
};
